from _game import tools
L = tools["run_lua"]
print(L("local s=game.surfaces.fulgora local o={} for _,e in pairs(s.find_entities_filtered{type={'container','logistic-container'}}) do local c=e.get_inventory(defines.inventory.chest).get_item_count('holmium-plate') local d=e.get_inventory(defines.inventory.chest).get_item_count('holmium-ore') if c>0 or d>0 then o[#o+1]=e.name..' '..e.position.x..','..e.position.y..' plate '..c..' ore '..d end end local m={} for _,e in pairs(s.find_entities_filtered{type='assembling-machine'}) do local r=e.get_recipe() if r and (r.name=='holmium-plate' or r.name=='holmium-solution') then m[#m+1]=e.name..' '..r.name..' '..e.position.x..','..e.position.y..' st'..e.status end end rcon.print(table.concat(o,string.char(10))..string.char(10)..'machines '..#m..string.char(10)..table.concat(m,string.char(10)))"))
print(L("local pad=game.surfaces.fulgora.find_entities_filtered{type='cargo-landing-pad'}[1] for _,pt in pairs(pad.get_logistic_point()) do rcon.print('fulgora pad mode '..pt.mode..' trash_not_requested='..tostring(pt.trash_not_requested)..' network '..tostring(pt.logistic_network and pt.logistic_network.network_id)) end local pa=game.surfaces.aquilo.find_entities_filtered{type='cargo-landing-pad'}[1] for _,pt in pairs(pa.get_logistic_point()) do rcon.print('aquilo pad mode '..pt.mode..' trash_not_requested='..tostring(pt.trash_not_requested)) end"))
